def get_odd_collatz(n):
    """
    Given a positive integer n, return a sorted list containing the odd numbers
    that appear in its Collatz sequence (including 1).
    """
    odds = set()
    current = n
    while True:
        if current % 2 == 1:
            odds.add(current)
            if current == 1:
                break
            current = 3 * current + 1
        else:
            current //= 2
    return sorted(odds)
