def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    try:
        return sorted(set(l))
    except TypeError:
        # Fallback for unhashable elements (e.g., lists inside the list)
        unique_elems = []
        for item in l:
            if item not in unique_elems:
                unique_elems.append(item)
        return sorted(unique_elems)
